functions.get_text_pattern:
def get_text_pattern(text, text_pattern=None, return_vector=True):
    max_len = 40
    symbols = ['•', '-', '*', '+', '<', '>', '(', ')', '→', '✓', '#', '□', '■', '‣', '◦', '▪', '.', ':', '※', '']
    if text_pattern is None:
        pattern = ''
        for c in text:
            if c in symbols:
                pattern += c
            elif c.isspace():
                pattern += 'W'
            elif c.isdigit():
                pattern += 'D'
            elif not c.isalnum():
                pattern += 'S'
            else:
                pattern += 'C'

        compressed_pattern = ''
        prev_c = ''
        prev_repeat = 1
        for c_idx, c in enumerate(pattern):
            if c_idx == 0:
                compressed_pattern += c
            else:
                if prev_c == c:
                    prev_repeat += 1
                    continue
                else:
                    compressed_pattern += str(prev_repeat)
                    compressed_pattern += c
                    prev_repeat = 1
            prev_c = c
        if prev_c != '':
            compressed_pattern += str(prev_repeat)
        text_pattern = compressed_pattern

    if return_vector:
        vector = []
        for c in text_pattern:
            if c.isdigit():
                vector.append(int(c))
            elif c == 'C':
                vector.append(10)
            elif c == 'D':
                vector.append(11)
            elif c == 'S':
                vector.append(12)
            elif c == 'W':
                vector.append(13)
            elif c in symbols:
                vector.append(14 + symbols.index(c))
            else:
                raise Exception(f'Invalid pattern character: {c}')
        encoded = [format(v, '02o') for v in vector]
        encoded_vector = [0.0] * max_len
        cur_idx = 0
        for code in encoded:
            for c in code:
                encoded_vector[cur_idx] = int(c) / 8
                cur_idx += 1
                if cur_idx >= len(encoded_vector):
                    break
            if cur_idx >= len(encoded_vector):
                break
        return encoded_vector
    else:
        return text_pattern

functions.get_edge_attr:
def get_edge_attr(bboxes, edge_index, edge_type='', data_dict=None, page_img=None):
    """
    Compute edge attributes based on edge type.

    Args:
        bboxes: np.ndarray of shape (N, 4), float32
        edge_index: list of (i, j) tuples
        edge_type: str — '', 'SEO', 'PRS', etc.
        page_img: page image array (required for 'PRS')

    Returns:
        edge_attr: np.ndarray of shape (E, D)
    """
    if edge_type == 'SEO':
        return get_edge_transform_bbox_add_alignment(bboxes, edge_index)

    elif edge_type == 'PRS':
        from .presidio.graph import compute_edge_features
        page_h, page_w, _ = page_img.shape
        temp_edge_idx = np.array(edge_index).T
        return compute_edge_features(node_bboxes=bboxes, edge_index=temp_edge_idx,
                                     page_width=page_w, page_height=page_h)

    else:
        return get_edge_transform_bbox(bboxes, edge_index)

functions.get_rf_features:
def get_rf_features(custom_feature, rf_names, do_log_norm=False):
    f = []
    for f_name in rf_names:
        if f_name == 'is_text':
            if 'box_type' not in custom_feature or custom_feature['box_type'] == 'text':
                f.append(1.0)
            else:
                f.append(0.0)
        elif f_name == 'is_image':
            if 'box_type' in custom_feature and custom_feature['box_type'] == 'image':
                f.append(1.0)
            else:
                f.append(0.0)

        elif f_name == 'is_vector':
            if 'box_type' in custom_feature and custom_feature['box_type'] == 'vector':
                f.append(1.0)
            else:
                f.append(0.0)

        elif f_name == 'is_hline_vector':
            if 'box_type' in custom_feature and custom_feature['box_type'] == 'h-line-vector':
                f.append(1.0)
            else:
                f.append(0.0)

        elif f_name == 'is_vline_vector':
            if 'box_type' in custom_feature and custom_feature['box_type'] == 'v-line-vector':
                f.append(1.0)
            else:
                f.append(0.0)
        else:
            if f_name in IGNORE_FEATURE_NAMES:
                f.append(0.0)
            else:
                if f_name not in custom_feature:
                    raise Exception(f"'{f_name}' does not exist in 'custom_features'")

                try:
                    val = float(custom_feature[f_name])
                    if do_log_norm:
                        if f_name.startswith('context_') or f_name.startswith('is_') or f_name in ['fonts_offset', 'line_space',
                                                                                                   'linespaces_offset']:
                            pass
                        else:
                            val = math.log(val + 1e-8)
                    f.append(val)
                except Exception as ex:
                    print(f'{f_name} : {str(ex)}')
                    raise ex
    return f
